SELECT id, order_id, method, amount, paid_at, status, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY paid_at DESC, id) AS event_seq, ROUND(amount / SUM(amount) OVER (PARTITION BY method, order_id), 4) AS amount_share, AVG(amount) OVER (PARTITION BY status ORDER BY amount, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS amount_avg_2_prior, ROW_NUMBER() OVER w_running AS seq_no FROM payments WINDOW w_running AS (PARTITION BY method ORDER BY amount DESC, id)
